from __future__ import annotations

import json
from pathlib import Path
from typing import TYPE_CHECKING

import pytest
from ds.cli.ui import FRONTEND_URL, ready
from playwright.sync_api import sync_playwright

if TYPE_CHECKING:
    from collections.abc import Iterator

    from playwright.sync_api import Browser, Frame, Locator, Page

SYSTEM_CHROMIUM = Path("/usr/bin/chromium")  # Omarchy's; else the one `playwright install` gives
PANES = ("chat", "results", "python", "variables", "terminal")
# what a bar's children are, by their class (render.widget_bar)
BAR_PARTS = {
    "out-kind": "name",
    "spacer": "space",
    "strip-ask": "ask box",
    "ai-toggle": "ai",
    "ai-btn": "ai",
    "form-toggle": "inputs",
    "close-view-btn": "close",
    "float-btn": "float",
}


class App:
    """The app in one browser page, with the few moves the tests share."""

    def __init__(self, page: Page) -> None:
        self.page = page

    # -- panes
    def shown(self) -> list[str]:
        """The panes on screen, top to bottom, left to right."""
        return self.page.evaluate(
            """() => [...document.querySelectorAll('[data-pane]')].filter(n => n.getClientRects().length)
                 .sort((a, b) => { const [p, q] = [a.getBoundingClientRect(), b.getBoundingClientRect()];
                                   return p.top - q.top || p.left - q.left; })
                 .map(n => n.dataset.pane)"""
        )

    def show(self, *panes: str) -> None:
        """Make exactly these panes the ones on screen (by the bottom bar's toggles)."""
        for name in PANES:
            if (name in panes) != (name in self.shown()):
                self.page.click(f'[data-toggle="{name}"]')
                self.page.wait_for_function(
                    "([name, on]) => !!document.querySelector(`[data-pane='${name}']`).getClientRects().length === on",
                    arg=[name, name in panes],
                )
        if "terminal" in panes:
            self.terminal()  # its page has loaded and its shell answers

    def active(self) -> str:
        """The pane the cursor is in."""
        return self.page.evaluate("() => document.querySelector('[data-pane][data-active]')?.dataset.pane || ''")

    # -- chat
    @property
    def chat_box(self) -> Locator:
        return self.page.locator('textarea[name="prompt"]')

    def slash(self, command: str) -> None:
        """Run a slash command from the chat box, eg "/vods" (never a message to the AI)."""
        if not command.startswith("/"):
            msg = "only slash commands: an e2e test never sends the AI a message"
            raise ValueError(msg)
        self.chat_box.fill(command)
        self.page.keyboard.press("Escape")  # the list of commands
        self.chat_box.press("Enter")
        # its row in the chat (a command that clears the chat leaves its own row too)
        self.page.wait_for_function(
            "(command) => document.querySelector('.chat-items').innerText.includes(command)", arg=command
        )

    def slash_list(self, typed: str) -> list[str]:
        """The commands listed for what is typed; the one Enter would run ends with "*"."""
        self.chat_box.fill("")
        self.chat_box.type(typed)
        self.page.wait_for_selector(".slash-menu.is-open")
        return self.page.evaluate(
            """() => [...document.querySelectorAll('.slash-menu [data-slash]')].filter(r => !r.hidden)
                 .map(r => r.dataset.slash + (r.classList.contains('is-active') ? '*' : ''))"""
        )

    # -- python
    def run_cell(self, code: str) -> None:
        """Type code into the first Python cell and run it (Shift+Enter)."""
        self.page.click(".cell .cm-content")
        self.page.keyboard.type(code)
        self.page.keyboard.press("Shift+Enter")

    # -- widgets
    def widget(self, slot: str) -> Locator:
        """A widget by where it is shown, eg "chat:r1", "cell:c1"."""
        found = self.page.locator(f'.widget[data-slot="{slot}"]')
        found.wait_for(state="visible")
        return found

    @staticmethod
    def regions(widget: Locator) -> list[str]:
        """Its regions, top to bottom, by class (viewer-bar, tool-form, widget-display...)."""
        return widget.evaluate("w => [...w.children].map(c => c.className.split(' ')[0]).filter(Boolean)")

    @staticmethod
    def bar(widget: Locator) -> list[str]:
        """Its bar, left to right: name, space or ask box, ai, inputs, float, close."""
        classes = widget.evaluate("w => [...w.querySelector('.viewer-bar').children].map(c => c.className)")
        return [next((what for name, what in BAR_PARTS.items() if name in found.split()), found) for found in classes]

    @staticmethod
    def line(widget: Locator) -> list[str]:
        """Each thing in its bottom line, as text (a box: its placeholder); no spacer."""
        return widget.evaluate(
            """w => [...w.querySelector('.widget-line').children].filter(c => !c.classList.contains('spacer'))
                 .map(c => (c.textContent.trim() || c.placeholder || '').replace(/\\s+/g, ' '))"""
        )

    # -- terminal
    def terminal(self) -> Frame:
        """The Terminal's page, once its shell shows a prompt."""
        self.page.wait_for_selector('[data-pane="terminal"] iframe')
        for _ in range(100):  # the frame is in the page a moment before its address is
            if frame := next((found for found in self.page.frames if "/terminal" in found.url), None):
                break
            self.page.wait_for_timeout(100)
        else:
            pytest.fail("the Terminal's page didn't load")
        frame.wait_for_function("() => window.smashTerminal && window.smashTerminal.text().trim() !== ''")
        return frame

    def terminal_text(self) -> str:
        return self.terminal().evaluate("() => window.smashTerminal.text()")

    def wait_terminal_text(self, text: str) -> None:
        self.terminal().wait_for_function("(t) => window.smashTerminal.text().includes(t)", arg=text)

    def wait_terminal_focus(self, *, focused: bool) -> None:
        self.terminal().wait_for_function("(on) => document.hasFocus() === on", arg=focused)

    @property
    def strip_box(self) -> Locator:
        """The Terminal's Alt+I box, in its title strip."""
        return self.page.locator('[data-pane="terminal"] [data-strip-ask] .inline-box')


@pytest.fixture(scope="session")
def app_url() -> str:
    """The running app's address; one clear error when it isn't up."""
    if not ready():
        pytest.exit("delulu-smash isn't answering: start it with `ds ui restart`, then run this again.", returncode=1)
    return FRONTEND_URL


@pytest.fixture(scope="session")
def browser() -> Iterator[Browser]:
    with sync_playwright() as playwright:
        options = {"executable_path": str(SYSTEM_CHROMIUM)} if SYSTEM_CHROMIUM.exists() else {}
        try:
            found = playwright.chromium.launch(**options)
        except Exception as error:  # noqa: BLE001  # any launch failure gets the same advice
            pytest.exit(f"no Chromium to run the e2e tests in ({error}): `uv run playwright install chromium`", 1)
        yield found
        found.close()


@pytest.fixture
def app(browser: Browser, app_url: str) -> Iterator[App]:
    """The app, loaded in a fresh browser session (so a fresh app session). A JavaScript error
    on the page fails the test that caused it.
    """
    context = browser.new_context(viewport={"width": 1500, "height": 1100})
    page = context.new_page()
    errors: list[str] = []
    page.on("pageerror", lambda error: errors.append(str(error)))
    page.goto(app_url)
    # the app is ready once its state is connected: the chat box takes the cursor
    page.wait_for_selector('textarea[name="prompt"]')
    page.wait_for_function("() => window.smashPress && document.querySelector('[data-toggle=\"chat\"]')")
    page.wait_for_timeout(1500)  # the websocket's first sync: a toggle clicked before it is lost
    yield App(page)
    context.close()
    assert not errors, f"JavaScript errors on the page: {json.dumps(errors[:3])}"
